mapper.sql:
t.del_flag = 0

    AND (
        COALESCE(c.company_name, '') ILIKE CONCAT('%', #{query.keyword}, '%')
        OR COALESCE(p.name, '') ILIKE CONCAT('%', #{query.keyword}, '%')
        OR COALESCE(t.remark, '') ILIKE CONCAT('%', #{query.keyword}, '%')
    )

AND t.customer_id = #{query.customerId}
AND t.project_id = #{query.projectId}
AND t.owner_id = #{query.ownerId}
AND t.status = #{query.status}

mapper.update:
UPDATE ${table}
SET del_flag = 1,
    update_user_id = #{userId},
    update_time = CURRENT_TIMESTAMP
WHERE ${idColumn} = #{id}

mapper.select:
SELECT COALESCE(SUM(amount), 0)
FROM crm_finance_payment
WHERE del_flag = 0
  AND payment_date >= #{startDate}
  AND payment_date <= #{endDate}

SELECT COALESCE(SUM(amount), 0)
FROM crm_finance_expense
WHERE del_flag = 0
  AND expense_date >= #{startDate}
  AND expense_date <= #{endDate}

SELECT COALESCE(SUM(amount - received_amount), 0)
FROM crm_finance_receivable
WHERE del_flag = 0
  AND status IN ('pending', 'partial', 'overdue')
  AND due_date >= #{startDate}
  AND due_date <= #{endDate}
